import java.util.*;
import java.io.*;

public class e{

	static long mod = 998244353;

	public static void main(String[] args){
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		try{
			String[] parts = br.readLine().split(" ");
			long n = Long.parseLong(parts[0]);
			long m = Long.parseLong(parts[1]);
			long L = Long.parseLong(parts[2]);
			long R = Long.parseLong(parts[3]);
			long h = R-L;

			long e = 0;
			long o = 0;
			if(h % 2 == 1){
				long d = (h+1)/2;
				e = d;
				o = d;
			}
			else{
				long d = h/2;
				e = d;
				o = d;
				if(L % 2 == 1) o++;
				else e++;
			}

			long[][] matrix = {{e, o},{o, e}};
			long[][] result = matrixPower(matrix, m*n);
			long ans = result[0][0];
			if((n*m)%2==1) ans += result[0][1];
			System.out.println(ans%mod);
		}catch(Exception e){
			e.printStackTrace();
		}
	}

	static long[][] matrixPower(long[][] base, long exp){
		if(exp==0) return identity(base.length);
		if(exp%2==1){
			long[][] temp = matrixPower(base, exp-1);
			return multiply(temp, base);
		}
		long[][] half = matrixPower(base, exp/2);
		return multiply(half, half);
	}

	static long[][] identity(int size){
		long[][] id = new long[size][size];
		for(int i=0; i<size; i++) id[i][i]=1;
		return id;
	}

	static long[][] multiply(long[][] a, long[][] b){
		long[][] res = new long[a.length][b[0].length];
		for(int i=0; i<a.length; i++){
			for(int j=0; j<b[0].length; j++){
				for(int k=0; k<a[0].length; k++){
					res[i][j] += (a[i][k]%mod)*(b[k][j]%mod);
					res[i][j] %= mod;
				}
			}
		}
		return res;
	}
}
